class Ledger:
    def __init__(self):
        self.balances = {'source': 100, 'target': 0}
        self.fail_credit = False

    def debit(self, amount):
        self.balances['source'] -= amount
        return {'amount': amount, 'authorization': 'approved'}

    def credit(self, receipt):
        if receipt is None or receipt.get('authorization') != 'approved':
            raise ValueError('debit receipt required')
        if self.fail_credit:
            raise ValueError('credit rejected')
        self.balances['target'] += receipt['amount']

    def atomic_transfer(self, amount):
        before = self.balances.copy()
        try:
            receipt = self.debit(amount)
            self.credit(receipt)
        except Exception:
            self.balances = before
            raise

