import json
import sys

class PurchasePipeline:
    def __init__(self):
        self.steps = [self.decode, self.validate, self.normalize, self.format, self.envelope]

    def decode(self, value):
        return json.loads(value)

    def validate(self, value):
        if not isinstance(value, dict) or not isinstance(value.get('item'), str) or type(value.get('cents')) is not int or value['cents'] < 0:
            raise ValueError('invalid purchase')
        return value

    def normalize(self, value):
        return {'item': value['item'], 'cents': value['cents']}

    def format(self, value):
        return {'item': value['item'], 'total': f"${value['cents'] / 100:.2f}"}

    def envelope(self, value):
        return dict(value)

    def run(self, value):
        for step in self.steps:
            value = step(value)
        return value

def render(raw):
    return PurchasePipeline().run(raw)

if __name__ == '__main__':
    print(json.dumps(render(sys.argv[1])))
